function prefixSuggestions(words, typed) {
  const result = [];
  for (let i = 1; i <= typed.length; i++) {
    const prefix = typed.slice(0, i);
    result.push(words.filter((w) => w.startsWith(prefix)).sort().slice(0, 3));
  }
  return result;
}

function prefixSuggestions(words, typed) {
  const sorted = [...words].sort();
  const result = [];
  let low = 0;
  for (let length = 1; length <= typed.length; length++) {
    const prefix = typed.slice(0, length);
    let lo = low, hi = sorted.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (sorted[mid] < prefix) lo = mid + 1; else hi = mid;
    }
    low = lo;
    const picks = [];
    for (let i = lo; i < sorted.length && picks.length < 3 && sorted[i].startsWith(prefix); i++) picks.push(sorted[i]);
    result.push(picks);
  }
  return result;
}
